package com.hotel.controller;
import com.hotel.dao.impl.FrontDeskDaoImpl;import com.hotel.dto.*;import com.hotel.exception.*;import com.hotel.service.FrontDeskService;import com.hotel.service.impl.FrontDeskServiceImpl;import com.hotel.util.DBConnection;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/receptionist/check-in")public class CheckInServlet extends HttpServlet{private final FrontDeskService service=new FrontDeskServiceImpl(new FrontDeskDaoImpl(),DBConnection::getConnection);
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{String id=q.getParameter("identifier"),keyword=q.getParameter("keyword");if((id==null||id.isBlank())&&keyword!=null&&!keyword.isBlank())q.setAttribute("reservations",service.searchReservations(keyword));load(q,s,id);}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{String raw=q.getParameter("reservationId");try{long id=Long.parseLong(raw);SessionUser u=(SessionUser)q.getSession().getAttribute("sessionUser");Map<Long,List<Long>> rooms=parseRooms(q);service.checkIn(id,rooms,"on".equals(q.getParameter("documentsChecked")),u.userId());q.getSession().setAttribute("flashSuccess","Check-in thành công. Assignment, trạng thái phòng và draft invoice đã được lưu.");s.sendRedirect(q.getContextPath()+"/receptionist/check-in?identifier="+id);}catch(NumberFormatException|BusinessException e){q.setAttribute("error",e instanceof BusinessException?e.getMessage():"Reservation ID không hợp lệ.");q.setAttribute("selectedRooms",parseRooms(q));q.setAttribute("documentsChecked","on".equals(q.getParameter("documentsChecked")));load(q,s,raw);}catch(DataAccessException e){getServletContext().log("Check-in failed",e);s.sendError(500);}}
 private Map<Long,List<Long>> parseRooms(HttpServletRequest q){Map<Long,List<Long>> out=new LinkedHashMap<>();for(var e:q.getParameterMap().entrySet())if(e.getKey().startsWith("room_")){try{long rr=Long.parseLong(e.getKey().substring(5));List<Long> ids=new ArrayList<>();for(String x:e.getValue())ids.add(Long.parseLong(x));out.put(rr,List.copyOf(ids));}catch(NumberFormatException ignored){}}return out;}
 private void load(HttpServletRequest q,HttpServletResponse s,String id)throws ServletException,IOException{try{if(id!=null&&!id.isBlank()){var d=service.checkInDetails(id);if(d.isPresent())q.setAttribute("details",d.get());else q.setAttribute("error","Không tìm thấy reservation.");}Object f=q.getSession().getAttribute("flashSuccess");if(f!=null){q.setAttribute("success",f);q.getSession().removeAttribute("flashSuccess");}q.getRequestDispatcher("/WEB-INF/views/receptionist/check-in.jsp").forward(q,s);}catch(DataAccessException e){getServletContext().log("Check-in page failed",e);s.sendError(500);}}
}
